SELECT result_tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (SELECT result_tags AS result_tags, timestamp AS timestamp, any(value) AS value FROM (SELECT arrayFilter(tag -> tag.1 != '__name__', lhs.original_group) AS result_tags, lhs.timestamp AS timestamp, toFloat64(if((lhs.value = rhs.value), 1, 0)) AS value FROM (SELECT any(tags) AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, any(value) AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, argMax(d.value, d.timestamp) AS value FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({lhs_start_ms:Int64}, {lhs_end_ms:Int64} + {lhs_step_ms:Int64}, {lhs_step_ms:Int64}))) AS eval_ts FROM (
            SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {lhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64})
        ) AS series) AS grid INNER JOIN timeSeriesData(`observability`.`prometheus`) AS d ON d.id = grid.id WHERE d.timestamp >= fromUnixTimestamp64Milli({lhs_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({lhs_required_end_ms:Int64}) AND d.timestamp <= grid.eval_ts - toIntervalMillisecond({lhs_offset_ms:Int64}) AND d.timestamp >= grid.eval_ts - toIntervalMillisecond({lhs_offset_ms:Int64} + {lhs_lookback_ms:Int64}) GROUP BY grid.id, grid.tags, grid.eval_ts HAVING NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) ARRAY JOIN time_series AS point) GROUP BY arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)), timestamp HAVING throwIf(count() > 1, 'found duplicate series for the match group on the lhs hand-side of the operation') = 0) AS lhs INNER JOIN (SELECT any(tags) AS original_group, arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)) AS join_group, timestamp AS timestamp, any(value) AS value FROM (SELECT tags AS tags, point.1 AS timestamp, point.2 AS value FROM (
    SELECT tags AS tags, arraySort(item -> item.1, groupArray((timestamp, value))) AS time_series FROM (
        SELECT grid.tags AS tags, grid.eval_ts AS timestamp, argMax(d.value, d.timestamp) AS value FROM (SELECT series.id AS id, series.tags AS tags, arrayJoin(arrayMap(ts_ms -> fromUnixTimestamp64Milli(ts_ms), range({rhs_start_ms:Int64}, {rhs_end_ms:Int64} + {rhs_step_ms:Int64}, {rhs_step_ms:Int64}))) AS eval_ts FROM (
            SELECT src.id, arrayConcat([tuple('__name__', src.metric_name)], arrayMap((k, v) -> tuple(k, v), mapKeys(src.tags), mapValues(src.tags))) AS tags FROM timeSeriesTags(`observability`.`prometheus`) AS src WHERE src.metric_name = {rhs_range_instant_matcher_0_value:String} AND src.max_time >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND src.min_time <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64})
        ) AS series) AS grid INNER JOIN timeSeriesData(`observability`.`prometheus`) AS d ON d.id = grid.id WHERE d.timestamp >= fromUnixTimestamp64Milli({rhs_required_start_ms:Int64}) AND d.timestamp <= fromUnixTimestamp64Milli({rhs_required_end_ms:Int64}) AND d.timestamp <= grid.eval_ts - toIntervalMillisecond({rhs_offset_ms:Int64}) AND d.timestamp >= grid.eval_ts - toIntervalMillisecond({rhs_offset_ms:Int64} + {rhs_lookback_ms:Int64}) GROUP BY grid.id, grid.tags, grid.eval_ts HAVING NOT isNaN(value)
    ) GROUP BY tags ORDER BY tags
) ARRAY JOIN time_series AS point) GROUP BY arraySort(tag -> tag.1, arrayFilter(tag -> NOT has(['__name__'], tag.1), tags)), timestamp HAVING throwIf(count() > 1, 'found duplicate series for the match group on the rhs hand-side of the operation') = 0) AS rhs ON lhs.join_group = rhs.join_group AND lhs.timestamp = rhs.timestamp) GROUP BY result_tags, timestamp HAVING throwIf(count() > 1, 'multiple matches for labels: grouping labels must ensure unique matches') = 0) GROUP BY result_tags ORDER BY result_tags
SETTINGS allow_experimental_time_series_table = 1
FORMAT JSONEachRow
